arguments.command:
cat << 'EOF' > /tmp/test_stackalloc_nint.cs
using System;

Span<nint> span = stackalloc nint[4];
span[0] = 10;
span[1] = 20;
span[2] = 30;
span[3] = 40;

Console.WriteLine($"Length: {span.Length}");
Console.WriteLine($"Element size: {nint.Size} bytes");
for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"  span[{i}] = {span[i]}");
EOF
dotnet run --project /dev/null 2>/dev/null || dotnet-script /tmp/test_stackalloc_nint.cs 2>/dev/null || (cd /tmp && dotnet new console -n TestNint --force -o TestNint > /dev/null 2>&1 && cp test_stackalloc_nint.cs TestNint/Program.cs && dotnet run --project TestNint)

